function send(msg        )       {
  process.stdout.write(JSON.stringify(msg) + '\n');
}

/** A stdio MCP server: one JSON-RPC message per line, answering initialize, ping, tools/list and tools/call. */
export function serveMcp(name        , tools           , toolCall                                                                  )       {
  const handle = async (msg                                                                     )                => {
    const reply = (result         ) => { if (msg.id !== undefined) send({ jsonrpc: '2.0', id: msg.id, result }); };
    switch (msg.method) {
      case 'initialize':
        return reply({
          protocolVersion: typeof msg.params?.protocolVersion === 'string' ? msg.params.protocolVersion : '2025-06-18',
          capabilities: { tools: {} },
          serverInfo: { name, version: '1.0.0' },
        });
      case 'ping':
        return reply({});
      case 'tools/list':
        return reply({ tools });
      case 'tools/call':
        return reply(await toolCall(String(msg.params?.name ?? ''), (msg.params?.arguments ?? {})                           ));
      default:
        if (msg.id !== undefined && msg.method) send({ jsonrpc: '2.0', id: msg.id, error: { code: -32601, message: `unknown method ${msg.method}` } });
    }
  };
  let buf = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk        ) => {
    buf += chunk;
    for (let i; (i = buf.indexOf('\n')) >= 0;) {
      const line = buf.slice(0, i).trim();
      buf = buf.slice(i + 1);
      if (!line) continue;
      let msg                              ;
      try {
        msg = JSON.parse(line);
      } catch {
        send({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'parse error' } });
        continue;
      }
      handle(msg).catch((e) => send({ jsonrpc: '2.0', id: msg?.id ?? null, error: { code: -32603, message: e instanceof Error ? e.message : String(e) } }));
    }
  });
  process.stdin.on('end', () => process.exit(0));
}
